#include "modules/cgGR/cgGR.h"
#include "tests/testData.h"
#include <gtest/gtest.h>

namespace UnitTest
{
class CGGRModuleTest : public ::testing::Test
{
    protected:
    DissolveSystemTest systemTest;
};

// Validates against MuSSIC's own CG-unweighted-*.gr reference output (tests/music-reference/
// cg_dimer_gas/), generated by running MuSSIC itself on the same synthetic trajectory
// (tests/data/cg-port/cg_dimer_gas.xyz) - see docs/ai-port/MIGRATION_DESIGN.md Increment 2.
TEST_F(CGGRModuleTest, DimerGas)
{
    ASSERT_NO_THROW_VERBOSE(systemTest.setUp("dissolve/input/cgGR-dimerGas.txt"));
    ASSERT_TRUE(systemTest.dissolve().iterate(3));

    // Agreement with MuSSIC's own output is ~1e-29 (floating-point noise) - this is validating
    // that a ported implementation reproduces MuSSIC's exact arithmetic, not a noisy
    // code-vs-experiment comparison, so a tight tolerance is both achievable and the right test
    // (see docs/ai-port/MIGRATION_DESIGN.md section 3 on tolerance).
    EXPECT_TRUE(systemTest.checkData1D(
        "CGGR01//Bulk//OriginalGR//BA-BA//Full",
        {"cg-port/CG-unweighted-BA-BA.gr", Data1DImportFileFormat::Data1DImportFormat::XY, 1, 2}, 1.0e-6));
    EXPECT_TRUE(systemTest.checkData1D(
        "CGGR01//Bulk//OriginalGR//BA-BB//Full",
        {"cg-port/CG-unweighted-BA-BB.gr", Data1DImportFileFormat::Data1DImportFormat::XY, 1, 2}, 1.0e-6));
    EXPECT_TRUE(systemTest.checkData1D(
        "CGGR01//Bulk//OriginalGR//BB-BB//Full",
        {"cg-port/CG-unweighted-BB-BB.gr", Data1DImportFileFormat::Data1DImportFormat::XY, 1, 2}, 1.0e-6));
    EXPECT_TRUE(systemTest.checkData1D(
        "CGGR01//Bulk//OriginalGR//Total",
        {"cg-port/CG-unweighted-total.gr", Data1DImportFileFormat::Data1DImportFormat::XY, 1, 2}, 1.0e-6));

    // BA-BB bound (intramolecular) partial: every dimer contributes exactly one BA-BB
    // intramolecular pair at the synthetic "bond" distance (~3.0 Angstroms, see
    // tests/music-reference/cg_dimer_gas/generate_cg_trajectory.py) - a genuinely non-zero case,
    // unlike BA-BA/BB-BB which have no intramolecular pairs possible in a two-bead-type dimer.
    EXPECT_TRUE(systemTest.checkData1D(
        "CGGR01//Bulk//OriginalGR//BA-BB//Bound",
        {"cg-port/CG-unweighted-BA-BB.gr", Data1DImportFileFormat::Data1DImportFormat::XY, 1, 3}, 1.0e-6));
}

} // namespace UnitTest
